async function fetchJson(file,optional=false){const r=await fetch(file);if(!r.ok){if(optional)return{};throw Error(`讀取失敗 (${r.status})：${file}`);}return r.json();}
async function loadDoc(id){if(cache.has(id))return cache.get(id);const d=meta(id);if(!d)throw Error('找不到這份文件。');const pending=Promise.all([fetchJson('data/'+(d.file||id+'.json').replace(/^data\//,'')),fetchJson('data/zh/'+id+'.json',true)]).then(([doc,zh])=>{doc.zh=zh;for(const section of doc.sections){const stack=[];section.scopes={};for(const block of section.blocks){const marker=block.en.match(/^\s*\(([^)]+)\)/);if(marker){const depth=Number(block.indent)||0;stack[depth]=marker[1];stack.length=depth+1;}section.scopes[block.id]=[...stack];}}return doc;});cache.set(id,pending);try{return await pending;}catch(e){cache.delete(id);throw e;}}
