function renderLibrary(){currentDoc=null;$('#companion').innerHTML=companionHome();$('#main').innerHTML=`<div class="library-intro"><div class="intro-top"><span class="eyebrow">YOUR MIGRATION LAW LIBRARY</span><span class="edition-pill">英文原文 × 繁體中文</span></div><h1>把法條，讀得清楚。</h1><p>一個可以慢慢讀、隨時查、接著讀的移民法書庫。<br>從法律架構到簽證條件，讓每一個引用都有來處。</p></div>${lastResume()}${caseLibraryTeaser()}<div class="section-title"><h2>核心法規</h2><small>01 / 法律與具體要求</small></div><div class="book-grid">${catalog.filter(d=>categoryOf(d)==='core').map((d,i)=>`<a class="book-card" href="#/book/${d.id}"><div class="book-number">${i===0?'I':'II'}</div><h3>${esc(short(d))}</h3><div class="english-name">${esc(d.title)}</div><p>${esc(descriptions[d.id]||'')}</p><footer><span>版本 ${date(d.version)} · ${d.sectionCount.toLocaleString()} 個章節／條目</span><span class="card-arrow">↗</span></footer></a>`).join('')}</div>${categories.filter(c=>c[0]!=='core').map(([id,title,n])=>`<div class="section-title"><h2>${title}</h2><small>${n}</small></div><div class="document-list">${catalog.filter(d=>categoryOf(d)===id).map(d=>`<a class="document-row" href="#/book/${d.id}"><div><h3>${esc(short(d))}</h3><small>${esc(d.title)}<br>${esc(descriptions[d.id]||'')} · 版本 ${date(d.version)}</small></div><span class="tag">${d.blockCount?.toLocaleString()} 段／區塊 ↗</span></a>`).join('')}${id==='policy'?resourceRows():id==='competency'?`<a class="document-row" href="https://legaltrainingaustralia.com/media/Capstone-SampleAssessment.pdf" target="_blank" rel="noopener"><div><h3>Capstone 公開案例與評核範例 ↗</h3><small>Legal Training Australia · 外部原始文件；未重製全文</small></div><span class="tag">原始 PDF</span></a>`:''}</div>`).join('')}<p class="source-note">${catalog.length} 份已匯入文件 · ${catalog.reduce((n,d)=>n+d.blockCount,0).toLocaleString()} 個原文段落與表格區塊。<br>中文為非官方翻譯，機器翻譯與另行核對的條文分別標示。<a href="#/about">來源、版本與閱讀說明 →</a></p>`;}
