 let renderedPath=null,renderedQuery='',restoration=0;
 const labelFor=(name,path)=>{const h=doc.sections.find(s=>s.isHeading&&s.title===name&&prefix(s.path,path));return h?zhTitle(doc,h):name.replace(/^Volume (\d+)/,'第 $1 卷');};
 $('#companion').innerHTML='<div class="aside-label">ON THIS DOCUMENT</div><h3>章節目錄</h3><input class="toc-search" id="toc-search" aria-label="搜尋章節目錄" placeholder="找法條編號或名稱"><div class="toc-hierarchy" id="toc-hierarchy"></div><div class="toc-scroll" id="toc-list" tabindex="0" role="navigation" aria-label="章節條目"></div><div class="toc-meta">'+doc.sections.length.toLocaleString()+' 個章節／條目 · 版本 '+date(doc.version)+'</div><a class="aside-link" href="#/book/'+doc.id+'">開啟本文件完整目錄 →</a><div class="progress-track"><div class="progress-fill" style="width:'+pct(doc.id)+'%"></div></div><p style="margin-top:10px">閱讀位置會自動保存；點段落旁的 ▱ 可另加書籤。</p>';
