function renderBookmarks(){currentDoc=null;$('#companion').innerHTML=`<div class="aside-label">LOCAL READING RECORDS</div><h3>你的閱讀紀錄</h3><p>書籤、段落位置與顯示偏好保存在此瀏覽器的 localStorage。</p><p>清除網站資料或換裝置時不會自動同步。你可以匯出備份，再於另一個瀏覽器匯入。</p><hr class="side-rule"><button class="small-button" id="export-records">匯出書籤與進度 ↓</button><br><br><button class="small-button" id="import-records">匯入備份 ↑</button>`;$('#main').innerHTML=`<div class="library-intro"><span class="eyebrow">YOUR PERSONAL MARGINS</span><h1>我的書籤</h1><p>留住想再讀一次的段落。${state.bookmarks.length} 個書籤，僅你目前的瀏覽器可見。</p></div><div class="mobile-backup"><button class="small-button" data-export>匯出備份 ↓</button> <button class="small-button" data-import>匯入備份 ↑</button></div>${lastResume()}${state.bookmarks.length?state.bookmarks.map(b=>`<article class="bookmark-card"><header><div><span class="eyebrow">${esc(short(meta(b.doc)))}</span><h3><a href="${routeFor(b.doc,b.section,b.block)}">${esc(b.title)}</a></h3></div><button class="icon-button" data-delete-bookmark="${esc(b.id)}" aria-label="移除此書籤">×</button></header><p>${esc(b.quote.slice(0,220))}${b.quote.length>220?'…':''}</p><label class="muted">我的筆記 <input data-note="${esc(b.id)}" value="${esc(b.note||'')}" placeholder="留一句提醒自己的話" style="width:100%;font-size:12px;margin:8px 0 16px"></label><footer><span>${new Date(b.createdAt).toLocaleDateString('zh-TW')}</span><a href="${routeFor(b.doc,b.section,b.block)}">回到這一段 →</a></footer></article>`).join(''):'<div class="empty">還沒有書籤。<br>閱讀時點段落左側的 ▱，就能把這一段留在這裡。</div>'}`;$$('[data-delete-bookmark]').forEach(b=>b.onclick=()=>{state.bookmarks=state.bookmarks.filter(x=>x.id!==b.dataset.deleteBookmark);save();renderBookmarks();});$$('[data-note]').forEach(i=>i.onchange=()=>{const b=state.bookmarks.find(x=>x.id===i.dataset.note);if(b)b.note=i.value;save();});$('#export-records').onclick=exportRecords;$('#import-records').onclick=()=>$('#import-file').click();$('[data-export]').onclick=exportRecords;$('[data-import]').onclick=()=>$('#import-file').click();}
function exportRecords(){const url=URL.createObjectURL(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='migration-reading-bookmarks-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已匯出書籤、筆記與閱讀進度');}
function renderAbout(){currentDoc=null;$('#companion').innerHTML=companionHome();$('#main').innerHTML=`<div class="library-intro"><span class="eyebrow">A NOTE ON THIS READING ROOM</span><h1>好好讀，也知道讀的是什麼。</h1></div><div class="about-prose"><h2>兩種閱讀方式</h2><p>所有內容統一採長文閱讀，將同一章、節或簽證的條文按順序排列，每頁最多十條。工具列的「本章目錄」可展開子章節並直接跳轉。每種簽證有自己的總覽頁，條文仍各有獨立網址。</p><h2>先看白話總結，再讀條文</h2><p>長文頁的導讀依章節及本頁條文整理，選列主要要求、限制與例外，並附對照連結。部分技術條目採來源濃縮；摘要仍須與完整英文核對，不替代全部法律要求。</p><h2>逐段對照，不把排版換行當成法條</h2><p>中文與英文依官方法定段落、分項和表格區塊對齊；(1)、(a)、(i) 等編號保留。文字會依螢幕重新換行，因此比照 PDF 的物理行數更適合逐段研讀。表格會保留原始儲存格順序，以「 | 」分隔；複雜表格請同時開啟官方原文核對。</p><h2>來源與版本</h2><p>法律原文來自澳洲 Federal Register of Legislation；能力標準及部長指示來自 OMARA／Home Affairs。每份文件標明版本與官方連結，匯入時保存來源及 SHA-256。<strong>版本日期不是「保證今天最新」的標章。</strong>處理案件時須再核對後續修法、適用及過渡規定。</p><h2>中文翻譯</h2><p>一般正文由 Google Translate 批次產生繁體中文；修法沿革表的部分區塊依官方縮寫表作中文展開，全部數字及文書編號保留。正文並標示「機器翻譯・未逐條人工校對」。特別核對的重點條文另作標示；這些仍是非官方翻譯。法規沒有個別標題時，部分條文另加研讀短名；短名與「研讀提示」均是編輯說明。中文不具有官方英文的法律地位，尤其應逐一核對 and／or、unless、時點與期限。閱讀時可隨時切換純英文。</p><h2>引用預覽與跳轉</h2><p>將游標移至帶點線的法條引用，或以 Tab 聚焦，即可預覽目標的標題、中文與原文。游標可移入浮窗繼續閱讀，按 Esc 關閉。點擊引用會跳至對應法條；帶有分款的引用會盡量定位到該款。未匯入或無法唯一辨認的引用會清楚標示，並連至來源頁，不憑空補寫內容。</p><h2>書籤與隱私</h2><p>書庫公開，不需註冊。書籤、筆記、最近閱讀位置、目錄層級、捲動與展開狀態，以及文字設定，只儲存在目前瀏覽器，不傳送至伺服器。字型由 Google Fonts 提供；所有已匯入的中文翻譯都隨網站載入，不會把你的筆記送去翻譯。可在「我的書籤」匯出及匯入 JSON 備份。</p><h2>申請實務案例</h2><p>案例庫以公開的官方調查、紀律決定、法律援助及承辦機構個案紀錄為來源。原案事實、移民局結果、後續處理與研讀分析分列。機構自述不冒稱官方裁決；未公開的附件、時點及結果不補寫。每案都列原始來源與資料缺口。</p><h2>哪些材料只有入口？</h2><p>LIN 文件隨簽證及個案而不同，本書庫沒有宣稱收齊所有指定文書。LEGENDcom 的訂閱政策資料只提供官方入口。LTA Capstone 範例保留原始文件連結，沒有重製完整考題。</p><h2>閱讀樣式的依據</h2><ul><li><a href="https://design-system.service.gov.uk/styles/layout/" target="_blank" rel="noopener">GOV.UK Layout</a>：控制長文行寬、適應不同螢幕。</li><li><a href="https://design-system.service.gov.uk/styles/type-scale/" target="_blank" rel="noopener">GOV.UK Type scale</a>：一致的字級及行距層級。</li><li><a href="https://www.legislation.gov.uk/help" target="_blank" rel="noopener">Legislation.gov.uk</a>：章節導覽、原始與修訂版本、修法狀態的區分。</li><li><a href="https://www.w3.org/WAI/WCAG21/Understanding/content-on-hover-or-focus.html" target="_blank" rel="noopener">W3C 1.4.13</a>：浮窗可關閉、可移入、保留足夠閱讀時間。</li><li><a href="https://www.w3.org/WAI/WCAG21/Understanding/text-spacing.html" target="_blank" rel="noopener">W3C 1.4.12</a>：文字間距可調整，內容仍可閱讀操作。</li></ul><h2>文件清單</h2>${catalog.map(d=>`<p style="font-size:12px"><a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener">${esc(d.title)}</a><br>版本 ${esc(d.version)} · ${d.blockCount} 段／區塊</p>`).join('')}<p class="muted">能力標準：© Commonwealth of Australia，依原文件 Creative Commons Attribution 3.0 Australia 授權使用。中文翻譯及重新排版為本閱讀室的衍生內容。</p></div>`;}
async function route(){cleanupChapterMenu();cleanupChapterMenu=()=>{};captureNavigation();captureTocState=()=>{};captureBookState=()=>{};syncTocSelection=()=>{};syncBookSelection=()=>{};const explicitSelection=pendingSelection?.href===location.hash;pendingSelection=null;const token=++renderToken;observer?.disconnect();clearTimeout(progressTimer);hidePreview();const raw=location.hash.slice(1)||'/library';const [path,query='']=raw.split('?');const parts=path.split('/').filter(Boolean).map(decodeURIComponent);const type=parts[0]||'library';currentRoute={type,doc:parts[1],section:parts[2]};renderNav();$('#sidebar').classList.remove('open');if(type!=='read'&&type!=='chapter')document.body.classList.remove('focus-reading');window.scrollTo(0,0);try{if(type==='library')renderLibrary();else if(type==='bookmarks')renderBookmarks();else if(type==='about')renderAbout();else if(type==='cases')renderCases();else if(type==='case')renderCase(parts[1]);else{const id=parts[1];$('#main').innerHTML='<div class="loading"><span class="spinner"></span>正在開啟原文與中文對照…</div>';const doc=await loadDoc(id);if(token!==renderToken)return;if(explicitSelection){const selected=doc.sections.find(section=>section.id===parts[2]||type==='visa'&&section.isHeading&&/^Subclass\s+/.test(section.title)&&section.title.match(/^Subclass\s+(\d+)/)?.[1]===parts[2]);if(selected)prepareSelectedRoute(doc,selected);pendingSelection=null;}if(type==='book')renderBook(doc);else if(type==='visa')renderVisa(doc,parts[2]);else if(type==='lookup'){const s=doc.sections.find(s=>s.number===parts[2]);if(!s)throw Error('本版本找不到這個法條編號。');location.replace(routeFor(id,s.id));return;}else{const s=doc.sections.find(s=>s.id===parts[2]);if(!s)throw Error('找不到這條規定，請從文件目錄重新選擇。');renderRead(doc,s,new URLSearchParams(query));}}$('#main').focus({preventScroll:true});}catch(e){$('#main').innerHTML=`<div class="error"><h2>這一頁暫時無法開啟</h2><p>${esc(e.message)}</p><a href="#/library">返回書庫 →</a></div>`;console.error(e);}}
let searchWorker,searchCounter=0;
function setupSearch(){searchWorker=new Worker('search-worker.js',{type:'module'});searchWorker.onmessage=e=>{const {id,results,total,error}=e.data;if(id!==searchCounter)return;if(error){$('#search-status').textContent=error;return;}const caseQuery=$('#global-search').value.trim().toLowerCase(),caseHits=caseRecords.filter(record=>(record.title+' '+record.summary+' '+(record.visas||[]).join(' ')+' '+record.timeline.map(item=>item.text).join(' ')).toLowerCase().includes(caseQuery));$('#search-status').textContent=`找到 ${total} 個符合的條目${total>60?'，顯示前 60 個':''}`;$('#search-results').innerHTML=results.map(r=>`<a class="search-result" href="${routeFor(r.doc,r.id,r.block||'')}"><span class="eyebrow">${esc(short(meta(r.doc)))} · ${esc(r.number||'')}</span><strong>${esc(r.zh||r.title)}</strong><small>${esc(r.snippet||r.title)}</small></a>`).join('')||'<p class="empty">沒有找到。可試試完整編號，例如 155.212。</p>';if(caseHits.length){if(!results.length)$('#search-results').innerHTML='';$('#search-results').insertAdjacentHTML('afterbegin',caseHits.slice(0,6).map(record=>`<a class="search-result" href="#/case/${record.id}"><span class="eyebrow">申請實務案例 · ${esc(record.period)}</span><strong>${esc(record.title)}</strong><small>${esc(record.departmentResult)}</small></a>`).join(''));$('#search-status').textContent+=` · 另有 ${caseHits.length} 個案例（最多顯示 6 案）`;}$$('#search-results a').forEach(a=>a.onclick=()=>$('#search-dialog').close());};let timer;$('#global-search').oninput=()=>{clearTimeout(timer);const q=$('#global-search').value.trim();if(q.length<2){$('#search-status').textContent='請輸入至少兩個字元';$('#search-results').innerHTML='';return;}$('#search-status').textContent='正在搜尋全文…';timer=setTimeout(()=>searchWorker.postMessage({id:++searchCounter,q}),180);};$('#search-open').onclick=()=>{$('#search-dialog').showModal();$('#global-search').focus();};}
function hidePreview(){clearTimeout(hoverTimer);hoverToken++;$('#ref-preview').hidden=true;}
async function showPreview(link){const token=++hoverToken;const box=$('#ref-preview');box.dataset.originBlock=link.closest('.line-pair')?.id||'';box.dataset.originSection=link.closest('.line-pair')?.dataset.section||'';box.innerHTML=`<div class="eyebrow">REFERENCE PREVIEW</div><button class="icon-button preview-close" aria-label="關閉引用預覽">×</button><h3>${esc(link.dataset.refLabel||'引用')}</h3><p class="muted">正在查閱來源…</p>`;box.hidden=false;positionPreview(link);box.querySelector('.preview-close').onclick=hidePreview;try{const id=link.dataset.refDoc;let html;if(link.dataset.refExternal){html=`<p>此引用未匯入，或目前無法唯一辨認其目標。請開啟官方來源，以引用編號核對相應條文。</p><footer><a href="${esc(link.href)}" target="_blank" rel="noopener">開啟來源原文 ↗</a><span class="muted">未補寫條文內容</span></footer>`;}else{const doc=await loadDoc(id);if(token!==hoverToken)return;const s=doc.sections.find(s=>s.id===link.dataset.refSection);if(link.dataset.refVisa){const v=visaGroups(doc).find(v=>v.number===link.dataset.refVisa);const guide=v?buildPageSummary(doc,v.sections,chapterSummaries,v.heading,section=>zhTitle(doc,section)):null;html=`<h3>${esc(v?.heading?zhTitle(doc,v.heading):'Subclass '+link.dataset.refVisa)}</h3>${guide?.overview?`<p>${esc(guide.overview)}</p><p class="muted">編輯摘要 · 非條文原文</p>`:''}<p>${v?.sections.filter(s=>!s.isHeading).length||0} 條簽證規定；詳見此版本的資格、例外與附加條件。</p><footer><a href="${esc(link.getAttribute('href'))}">開啟簽證專頁 →</a><span class="muted">${date(doc.version)}</span></footer>`;}else if(!s){html=`<h3>${esc(short(doc))}</h3><p>${esc(descriptions[doc.id]||'')}</p><footer><a href="#/book/${doc.id}">開啟文件目錄 →</a><span class="muted">${date(doc.version)}</span></footer>`;}else{const sub=link.dataset.refSub||'';let start=0;if(sub){const tokens=[...sub.matchAll(/\(([^)]+)\)/g)].map(m=>m[1]);for(const t of tokens){const found=s.blocks.findIndex((b,i)=>i>=start&&new RegExp('^\\s*\\('+t+'\\)').test(b.en));if(found>=0)start=found;}}const sample=s.blocks.slice(start,start+3);html=`<h3>${esc(zhTitle(doc,s))}</h3><p class="preview-en">${esc(s.title)}</p><div class="preview-quote">${sample.map(b=>`<p>${esc(zhBlock(doc,b)||b.en)}</p><p class="preview-en">${esc(b.en)}</p>`).join('')||'<p>此項為章節標題，點擊可閱讀下屬條文。</p>'}</div><p class="muted">以上為${sub?'引用分款起的':'條文開頭的'}原文及對照節錄。${isReviewed(doc,s)?'非官方中文已另行核對。':'機器翻譯，請核對英文。'}</p><footer><a href="${esc(link.getAttribute('href'))}">跳至 ${esc(link.dataset.refLabel)} →</a><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">官方原文 ↗</a></footer>`;}}if(token!==hoverToken)return;box.innerHTML=`<div class="eyebrow">${esc(meta(id)?.shortTitle||'REFERENCE')} · 引用預覽</div><button class="icon-button preview-close" aria-label="關閉引用預覽">×</button>`+html;box.querySelector('.preview-close').onclick=hidePreview;positionPreview(link);}catch(e){if(token===hoverToken)box.innerHTML='<p>無法載入引用預覽。點擊原引用可直接開啟來源。</p>';}}
function positionPreview(link){const box=$('#ref-preview'),r=link.getBoundingClientRect();const s=getReferenceIndex()?.docs?.[link.dataset.refDoc]?.sections.find(s=>s.id===link.dataset.refSection);const note=s?readingNotes[link.dataset.refDoc]?.[s.number]:null;if(note&&box.querySelector('.preview-quote')&&!box.querySelector('.reading-explanation'))box.querySelector('.preview-quote').insertAdjacentHTML('beforebegin',`<div class="reading-explanation"><strong>研讀提示 · 編輯說明</strong>${esc(note.text)}</div>`);const above=r.bottom+240>innerHeight&&r.top>innerHeight-r.bottom;const room=above?r.top-20:innerHeight-r.bottom-20;box.style.maxHeight=Math.max(80,Math.min(500,room))+'px';const left=Math.max(12,Math.min(r.left,innerWidth-box.offsetWidth-12));const top=above?Math.max(8,r.top-box.offsetHeight-8):r.bottom+8;box.style.left=left+'px';box.style.top=top+'px';}
function scheduleHide(){clearTimeout(hoverTimer);hoverTimer=setTimeout(hidePreview,250);}
document.addEventListener('mouseover',e=>{const a=e.target.closest('.ref-link');if(a){clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>showPreview(a),250);}});document.addEventListener('mouseout',e=>{if(e.target.closest('.ref-link')&&!e.relatedTarget?.closest('#ref-preview'))scheduleHide();});document.addEventListener('focusin',e=>{if(e.target.closest('.ref-link'))showPreview(e.target.closest('.ref-link'));});$('#ref-preview').onmouseenter=()=>clearTimeout(hoverTimer);$('#ref-preview').onmouseleave=scheduleHide;
document.addEventListener('click',e=>{const selected=e.target.closest('.toc-link');if(selected&&selected.getAttribute('href')===location.hash&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();jumpBlock('section-'+currentRoute.section);return;}const jump=e.target.closest('[data-summary-jump]');if(jump&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&document.getElementById('section-'+jump.dataset.summaryJump)){e.preventDefault();hidePreview();jumpBlock('section-'+jump.dataset.summaryJump);return;}const a=e.target.closest('a.ref-link, #ref-preview a');if(a&&a.getAttribute('href')?.startsWith('#/')){if(currentDoc&&currentRoute.section){const line=e.target.closest('.line-pair');const block=line?.id||$('#ref-preview').dataset.originBlock;const sec=line?.dataset.section||$('#ref-preview').dataset.originSection||currentRoute.section;referenceTrail={destination:a.getAttribute('href'),url:routeFor(currentDoc.id,sec,block),label:currentDoc.sections.find(s=>s.id===sec)?.number||'原條文'};}hidePreview();}if(!e.target.closest('#sidebar,#mobile-menu'))$('#sidebar').classList.remove('open');});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();$('#global-search').focus();}if(e.key==='Escape'){hidePreview();$('#sidebar').classList.remove('open');}});$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#font-size').oninput=e=>{state.prefs.fontSize=Number(e.target.value);applyPrefs();save();};$('#line-height').oninput=e=>{state.prefs.lineHeight=Number(e.target.value);applyPrefs();save();};$$('[data-theme]').forEach(b=>b.onclick=()=>{state.prefs.theme=b.dataset.theme;applyPrefs();save();});$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const imported=JSON.parse(await file.text());if(imported.version!==1||!Array.isArray(imported.bookmarks)||imported.bookmarks.some(b=>!b.doc||!b.section||!b.block||typeof b.quote!=='string'))throw Error('這不是有效的閱讀室備份。');const keys=new Set(state.bookmarks.map(b=>b.doc+'/'+b.block));for(const b of imported.bookmarks)if(!keys.has(b.doc+'/'+b.block)){state.bookmarks.push({...b,id:b.id||crypto.randomUUID(),note:String(b.note||'')});keys.add(b.doc+'/'+b.block);}if(imported.progress&&typeof imported.progress==='object')state.progress={...state.progress,...imported.progress};if(imported.last)state.last=imported.last;save();toast('備份已匯入，現有書籤也已保留');if(currentRoute.type==='bookmarks')renderBookmarks();}catch(err){toast(err.message);}e.target.value='';};
document.addEventListener('click',event=>{
 if(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
 const link=event.target.closest('a.section-item,a.chapter-read-link,a.visa-card,a.toc-link,a[data-chapter-section],a[data-summary-jump],a.ref-link');
 const href=link?.getAttribute('href');if(!href?.startsWith('#/'))return;
 const [path]=href.slice(1).split('?'),parts=path.split('/').filter(Boolean).map(decodeURIComponent);
 const inPage=(link.matches('[data-chapter-section],[data-summary-jump]')&&document.getElementById('section-'+parts[2]));
 pendingSelection=href===location.hash||inPage?null:{href};
 if(currentDoc?.id===parts[1]){
  const section=currentDoc.sections.find(section=>section.id===parts[2]||parts[0]==='visa'&&section.isHeading&&section.title.match(/^Subclass\s+(\d+)/)?.[1]===parts[2]);
  if(section){syncTocSelection(selectionPath(section),{section});if(parts[0]==='visa')prepareSelectedRoute(currentDoc,section);}
 }
},true);
window.addEventListener('hashchange',route);window.addEventListener('pagehide',captureNavigation);window.addEventListener('scroll',()=>{if(currentRoute.type==='book'){captureBookState();persistNavigationSoon();}else if(currentRoute.type==='cases'){state.navigation.cases.top=window.scrollY;persistNavigationSoon();}else if(currentRoute.type==='case'){(state.navigation.cases.reading ||= {})[currentRoute.doc]=window.scrollY;state.navigation.cases.lastCase=currentRoute.doc;persistNavigationSoon();}},{passive:true});applyPrefs();
try{const result=await Promise.all([fetchJson('data/catalog.json'),fetchJson('data/reference-index.json',true),fetchJson('data/reviewed-translations.json',true),fetchJson('data/heading-overrides.json',true),fetchJson('data/summaries-core.json',true),fetchJson('data/summaries-visas.json',true),fetchJson('data/summaries-supporting.json',true),fetchJson('data/summaries-transitions.json',true),fetchJson('data/cases.json')]);catalog=result[0];caseRecords=result[8].cases||[];setReferenceIndex(result[1]);chapterSummaries=mergeSummaries([...result.slice(5,8),result[4]]);reviewed=result[2];for(const [id,entry] of Object.entries(result[3]))reviewed[id]={...reviewed[id],items:{...entry.items,...reviewed[id]?.items}};renderNav();save();setupSearch();await route();}catch(e){$('#main').innerHTML=`<div class="error"><h2>書庫載入失敗</h2><p>${esc(e.message)}</p><button onclick="location.reload()">重新載入</button></div>`;}
